(function(){var b=document.querySelector('.menu-toggle'),n=document.querySelector('header nav');if(!b||!n)return;b.addEventListener('click',function(){var open=n.classList.toggle('is-open');b.setAttribute('aria-expanded',String(open));b.textContent=open?'Close menu':'Menu';});n.addEventListener('click',function(e){if(e.target.tagName==='A'&&window.matchMedia('(max-width:760px)').matches){n.classList.remove('is-open');b.setAttribute('aria-expanded','false');b.textContent='Menu';}});})();
